files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  min-block-size: 100dvb;
  margin: 0;
  color: var(--white, #fff);
  font-family: var(--main-font-family), sans-serif;
  font-size: var(--main-text-size, 18px);
  background-color: var(--purple);
}

h1,
h2,
h3,
p {
  margin: 0;
  padding: 0;
}

ul {
  padding: 0;
  list-style: none;
}

a {
  color: inherit;
  text-decoration: none;
}

h1 {
  border-radius: 4px;
  padding: 0.5em 1em;
  color: var(--white, #fff);
  font-weight: 800;
  font-size: var(--h1-font-size, 45px);
  text-transform: uppercase;
  background-color: rgb(0 0 0 / 0.8);
}

h2 {
  font-weight: 800;
  font-size: var(--h2-font-size, 38px);
  text-transform: uppercase;
}

h3 {
  font-weight: 800;
  font-size: var(--h3-font-size, 31px);
  text-transform: uppercase;
}

.visually-hidden {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: -1px;
  border: 0;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.header {
  display: grid;
  place-items: center;
  min-block-size: 100dvb;
}

.illustration {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: -1;
  inline-size: 100%;
  min-block-size: 100dvb;
  opacity: 1;
  transition: opacity 0.5s ease-in-out;
}

.text {
  inline-size: 80%;
  margin: 40px auto;
}

.text p:not(:last-child) {
  margin-block-end: 1em;
}

.footer {
  min-block-size: 100dvb;
}

.header__menu-button {
  position: fixed;
  inset: 0.8rem 0.8rem auto auto;
  display: block;
  inline-size: 50px;
  block-size: 50px;
  border: none;
  background-color: transparent;
  background-repeat: no-repeat;
  background-size: contain;
  transition: opacity 0.3s ease-in-out;
  cursor: pointer;
}

.header__menu-button_cmd_open {
  background-image: url(../svg/hamburger-open.svg);
}

.header__menu-button_cmd_close {
  background-image: url(../svg/hamburger-close.svg);
}

.header__menu-button:hover {
  opacity: 0.6;
}

.header__menu {
  position: fixed;
  inset: 0 0 0 auto;
  display: grid;
  place-items: center;
  inline-size: 100%;
  padding: 2em;
  color: var(--black);
  background-color: var(--blue);
  transition: translate 0.3s ease-in-out;
  translate: 100%;
}

.header__menu_is_opened {
  translate: 0;
}

.header__menu li:not(:last-child) {
  margin-block-end: 1em;
}

.header__menu a {
  display: block;
  font-weight: 800;
  text-align: center;
  text-transform: uppercase;
}

.header__menu a:hover {
  color: var(--white);
}
@media (orientation: landscape) {
  .header__menu {
    inline-size: 50%;
  }
}
